mapper.select:
select min(sign_date) as maxContinuousStartDate, count(*) as maxContinuousDays from user_checkin where user_id = #{userId}
and sign_date > #{preLevelDate}
group by stick_no order by maxContinuousDays desc limit 1

select min(uc.sign_date) curContinuousStartDate, count(*) curContinuousDays, uc.stick_no
from user_checkin uc
where user_id = #{userId}
group by stick_no
having stick_no = (select stick_no
                   from user_checkin
                   where user_id = #{userId}
                     and sign_date < #{targetData}
                    order by sign_date desc limit 1)

select max(sign_date) from (
     select sign_date from user_checkin uc

         uc.user_id = #{userId}

             uc.sign_date > #{fromDate}



         limit #{days}

 ) tmp
